<?php
require_once __DIR__.'/../includes/bootstrap.php';$admin=require_admin();$db=$GLOBALS['pdo'];$error='';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['subscription_id']??null,FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');$db->beginTransaction();try{$st=$db->prepare('SELECT * FROM subscriptions WHERE id=? FOR UPDATE');$st->execute([$id]);$sub=$st->fetch();if(!$sub)throw new RuntimeException('Permintaan tidak ditemukan.');if($sub['status']!=='pending')throw new RuntimeException('Permintaan sudah diproses.');if($action==='approve'){$db->prepare('UPDATE subscriptions SET status="active",starts_at=NOW(),ends_at=DATE_ADD(NOW(),INTERVAL 30 DAY),approved_by=? WHERE id=? AND status="pending"')->execute([$admin['id'],$id]);$db->prepare('UPDATE workspaces SET plan=? WHERE id=?')->execute([$sub['plan'],$sub['workspace_id']]);if((int)$sub['price_idr']>0){$db->prepare('UPDATE payments SET status="confirmed",confirmed_by=?,confirmed_at=NOW() WHERE subscription_id=? AND status="pending"')->execute([$admin['id'],$id]);}audit_log('subscription.approved','subscription',(int)$id,['plan'=>$sub['plan'],'amount_idr'=>(int)$sub['price_idr']]);$message='Permintaan diaktifkan setelah review admin. Tidak ada pembayaran kartu yang dilakukan oleh aplikasi.';}elseif($action==='reject'){$db->prepare('UPDATE subscriptions SET status="cancelled",approved_by=?,note=CONCAT(COALESCE(note,"")," · Ditolak manual oleh admin") WHERE id=?')->execute([$admin['id'],$id]);$db->prepare('UPDATE payments SET status="failed",confirmed_by=?,confirmed_at=NOW() WHERE subscription_id=? AND status="pending"')->execute([$admin['id'],$id]);audit_log('subscription.rejected','subscription',(int)$id);$message='Permintaan ditolak.';}else throw new RuntimeException('Tindakan tidak dikenali.');$db->commit();}catch(Throwable $exception){if($db->inTransaction())$db->rollBack();$error=$exception instanceof RuntimeException?$exception->getMessage():'Permintaan belum dapat diproses.';}}
$st=$db->query('SELECT s.*,u.name user_name,u.email,w.name workspace_name,w.plan workspace_plan,p.id payment_id,p.status payment_status,p.reference,p.amount_idr FROM subscriptions s JOIN users u ON u.id=s.user_id JOIN workspaces w ON w.id=s.workspace_id LEFT JOIN payments p ON p.subscription_id=s.id ORDER BY FIELD(s.status,"pending","active","expired","cancelled"),s.created_at DESC LIMIT 200');$subscriptions=$st->fetchAll();$revenue=(int)$db->query('SELECT COALESCE(SUM(amount_idr),0) FROM payments WHERE status="confirmed"')->fetchColumn();require_once __DIR__.'/../includes/header.php';$layout='admin';datanix_header('Admin subscriptions','subscriptions',$layout);
?>
<div class="admin-kicker">MANUAL REVIEW / NO GATEWAY</div><h1 class="admin-page-title">Subscriptions</h1><p class="admin-page-desc">Admin hanya menyetujui setelah verifikasi di luar aplikasi. Tombol di sini tidak memproses pembayaran dan tidak meminta detail kartu.</p><div class="admin-grid mb-3"><article class="admin-stat"><small>Pending</small><strong><?=e((int)$db->query('SELECT COUNT(*) FROM subscriptions WHERE status="pending"')->fetchColumn())?></strong><span>Awaiting human review</span></article><article class="admin-stat"><small>Active subscriptions</small><strong><?=e((int)$db->query('SELECT COUNT(*) FROM subscriptions WHERE status="active"')->fetchColumn())?></strong><span>All workspaces</span></article><article class="admin-stat"><small>Confirmed payments</small><strong><?=e((int)$db->query('SELECT COUNT(*) FROM payments WHERE status="confirmed"')->fetchColumn())?></strong><span>Manual records only</span></article><article class="admin-stat"><small>Actual recorded revenue</small><strong><?=e(format_money($revenue))?></strong><span>Confirmed payment ledger</span></article></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php elseif($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?>
<section class="admin-card"><div class="admin-card-head"><strong>Subscription requests</strong><span class="admin-badge">No automated billing</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>User / Workspace</th><th>Plan</th><th>Requested</th><th>Price example</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($subscriptions as $sub):?><tr><td><strong><?=e($sub['user_name'])?></strong><br><small><?=e($sub['email'])?> · <?=e($sub['workspace_name'])?></small></td><td><?=e(strtoupper($sub['plan']))?></td><td><?=e(date('d M Y H:i',strtotime($sub['created_at'])))?></td><td><?=e((int)$sub['price_idr']?format_money((int)$sub['price_idr']):'Custom / sample')?><br><small><?=e($sub['payment_status']??'No payment record')?></small></td><td><span class="admin-badge <?=$sub['status']==='active'?'good':($sub['status']==='pending'?'pending':'')?>"><?=e($sub['status'])?></span></td><td><?php if($sub['status']==='pending'):?><div class="admin-actions"><form method="post" data-confirm="Konfirmasi bahwa verifikasi manual sudah dilakukan, lalu aktifkan plan? Tidak ada charge otomatis."><?=csrf_field()?><input type="hidden" name="subscription_id" value="<?=e($sub['id'])?>"><input type="hidden" name="action" value="approve"><button class="btn btn-primary btn-sm">Approve</button></form><form method="post" data-confirm="Tolak permintaan upgrade ini?"><?=csrf_field()?><input type="hidden" name="subscription_id" value="<?=e($sub['id'])?>"><input type="hidden" name="action" value="reject"><button class="btn btn-light-outline btn-sm">Reject</button></form></div><?php else:?><span class="small-muted"><?=e($sub['ends_at']?date('d M Y',strtotime($sub['ends_at'])):'—')?></span><?php endif;?></td></tr><?php endforeach;?><?php if(!$subscriptions):?><tr><td colspan="6" class="text-center text-muted">Belum ada permintaan atau pembayaran tercatat.</td></tr><?php endif;?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
